def escape_cell(value, delimiter=","):
    text = "" if value is None else str(value)
    if any(char in text for char in (delimiter, '"', "\n", "\r")):
        return '"' + text.replace('"', '""') + '"'
    return text


def format_row(values, delimiter=","):
    return delimiter.join(escape_cell(value, delimiter) for value in values)


def export_csv(rows, header=None, delimiter=",", newline="\n"):
    lines = []
    if header is not None:
        lines.append(format_row(header, delimiter))
    lines.extend(format_row(row, delimiter) for row in rows)
    return newline.join(lines) + (newline if lines else "")
```

